/**
 * Demo catalog. Images are bundled SVG illustrations generated by
 * `npm run images:generate` (served by the web app from /products/*.svg),
 * so the demo never hot-links third-party images.
 */
export interface SeedCategory {
  slug: string;
  name: string;
  description: string;
  sortOrder: number;
}

export interface SeedProduct {
  slug: string;
  sku: string;
  name: string;
  description: string;
  category: string;
  priceCents: number;
  stock: number;
  tags: string[];
  rating: number;
  reviewCount: number;
  /** lucide icon used by the illustration generator */
  icon: string;
  /** gradient colors for the illustration */
  palette: [string, string];
}

